# ---------------------------------------------------------------------------
# Helper: compute derivatives of log-density via finite differences
# ---------------------------------------------------------------------------
compute_derivative <- function(x, log_f, h = 1e-5) {
  # Central difference for first derivative of log_f at x
  f_plus  <- log_f(x + h)
  f_minus <- log_f(x - h)
  if (is.infinite(f_plus) || is.infinite(f_minus)) return(NA_real_)
