    for (i in 1:m) {
      lo <- z_all[i]
      hi <- z_all[i + 1]
      if (abs(dfx[i]) < 1e-12) {
        areas[i] <- exp(fx[i]) * (hi - lo)
      } else {
        areas[i] <- exp(fx[i]) * (exp(dfx[i] * (hi - x[i])) - exp(dfx[i] * (lo - x[i]))) / dfx[i]
      }
    }

    total_area <- sum(areas)
    if (total_area <= 0 || is.na(total_area) || is.infinite(total_area)) {
      stop("Upper hull area is non-positive or invalid. The density may not be log-concave or the domain is invalid.")
    }

    # Sample a segment proportional to area
    probs <- areas / total_area
    seg <- sample(1:m, size = 1, prob = probs)

    # Sample uniformly from the exponential distribution on the chosen segment
    lo <- z_all[seg]
    hi <- z_all[seg + 1]
    a <- dfx[seg]
    b <- fx[seg] - dfx[seg] * x[seg]

    if (abs(a) < 1e-12) {
      samples[k + 1] <- runif(1, lo, hi)
    } else {
      u <- runif(1)
      samples[k + 1] <- log(u * exp(a * hi) + (1 - u) * exp(a * lo)) / a
    }

    # Squeeze test
    t_val <- fx[seg] + dfx[seg] * (samples[k + 1] - x[seg])

    # Lower hull value at the sampled point
    if (samples[k + 1] <= x[1]) {
      l_val <- fx[1]
    } else if (samples[k + 1] >= x[m]) {
      l_val <- fx[m]
    } else {
      l_val <- NA_real_
      for (i in 1:(m - 1)) {
        if (samples[k + 1] >= x[i] && samples[k + 1] <= x[i + 1]) {
          w <- (samples[k + 1] - x[i]) / (x[i + 1] - x[i])
          l_val <- fx[i] * (1 - w) + fx[i + 1] * w
          break
        }
      }
    }

    if (is.na(l_val)) {
      # Fallback: use the nearest tangent
      l_val <- fx[seg]
    }

    # Squeeze test
    if (log(runif(1)) <= l_val - t_val) {
      k <- k + 1
      next
    }

    # Rejection test: evaluate log_f at the sampled point
    f_sampled <- log_f(samples[k + 1], ...)
    if (is.na(f_sampled) || is.nan(f_sampled) || is.infinite(f_sampled)) {
