  }

  # Main sampling loop
  samples <- numeric(n)
  k <- 0L
  while (k < n) {
    m <- length(x)
    if (m < 2) stop("Not enough abscissae to construct hull.")

    # Compute intersection points between consecutive tangent lines
    z <- numeric(m - 1)
    for (i in 1:(m - 1)) {
