#   x * (dlogf(x_i) - dlogf(x_j)) = log_f(x_j) - log_f(x_i) + dlogf(x_i)*x_i - dlogf(x_j)*x_j + dlogf(x_j)*x_i - dlogf(x_i)*x_j ... wait let me redo
#   log_f(x_i) + dlogf(x_i)*(x - x_i) = log_f(x_j) + dlogf(x_j)*(x - x_j)
#   log_f(x_i) - dlogf(x_i)*x_i - log_f(x_j) + dlogf(x_j)*x_j = x*(dlogf(x_j) - dlogf(x_i))
#   x = (log_f(x_i) - dlogf(x_i)*x_i - log_f(x_j) + dlogf(x_j)*x_j) / (dlogf(x_j) - dlogf(x_i))
# ---------------------------------------------------------------------------
compute_intersection <- function(x_i, x_j, log_f_vals, dlogf_vals) {
  denom <- dlogf_vals[j] - dlogf_vals[i]
  if (abs(denom) < 1e-12) return(NA_real_)
  (log_f_vals[i] - dlogf_vals[i] * x_i - log_f_vals[j] + dlogf_vals[j] * x_j) / denom
