# ---------------------------------------------------------------------------
compute_intersection <- function(x_i, x_j, log_f_vals, dlogf_vals) {
  denom <- dlogf_vals[2] - dlogf_vals[1]
  if (abs(denom) < 1e-12) return(NA_real_)
  (log_f_vals[1] - dlogf_vals[1] * x_i - log_f_vals[2] + dlogf_vals[2] * x_j) / denom
}

# ---------------------------------------------------------------------------
# Main ARS function
# ---------------------------------------------------------------------------
ars <- function(log_f, n, x_init = NULL, domain = c(-Inf, Inf), ...) {
  # Validate inputs
  if (!is.function(log_f)) {
    stop("'log_f' must be a function that computes the (possibly unnormalized) log-density.")
  }
  if (!is.numeric(n) || length(n) != 1 || n < 1 || n != as.integer(n)) {
    stop("'n' must be a positive integer.")
  }
  if (!is.numeric(domain) || length(domain) != 2) {
    stop("'domain' must be a numeric vector of length 2.")
  }
  if (domain[1] >= domain[2]) {
    stop("'domain[1]' must be less than 'domain[2]'.")
  }

  n <- as.integer(n)
  lb <- domain[1]
  ub <- domain[2]

  # Default initial abscissae: 3 points spread across the domain
  if (is.null(x_init)) {
    if (is.infinite(lb) && is.infinite(ub)) {
      x_init <- c(-2, 0, 2)
    } else if (is.infinite(lb)) {
      x_init <- c(ub - 4, ub - 2, ub - 1)
    } else if (is.infinite(ub)) {
      x_init <- c(lb + 1, lb + 2, lb + 4)
    } else {
      x_init <- seq(lb + (ub - lb) * 0.2, ub - (ub - lb) * 0.2, length.out = 3)
    }
  }

  # Ensure initial points are within domain
  x_init <- sort(x_init)
  x_init <- x_init[x_init > lb & x_init < ub]
  if (length(x_init) < 2) {
    stop("Need at least 2 initial abscissae within the domain. Provide better 'x_init' or adjust 'domain'.")
  }

  # Initialize abscissae and their log-density values and derivatives
  x <- as.numeric(x_init)
  fx <- log_f(x)
  dfx <- sapply(x, function(xi) compute_derivative(xi, log_f))

  # Check log-concavity at initial points
  d2fx <- sapply(x, function(xi) compute_second_derivative(xi, log_f))
  if (any(d2fx > 1e-6, na.rm = TRUE)) {
    warning("Initial points may not satisfy log-concavity (second derivative of log-density > 0). ARS requires log-concave densities.")
  }

  # Main sampling loop
  samples <- numeric(n)
  k <- 0L
  while (k < n) {
    m <- length(x)
    if (m < 2) stop("Not enough abscissae to construct hull.")

    # Compute intersection points between consecutive tangent lines
    z <- numeric(m - 1)
    for (i in 1:(m - 1)) {
      z[i] <- compute_intersection(x[i], x[i + 1], fx[i:(i+1)], dfx[i:(i+1)])
      if (is.na(z[i])) {
        z[i] <- (x[i] + x[i + 1]) / 2
      }
    }

    # Extend z to cover the full domain
    z_all <- c(lb, z, ub)

    # Compute the area under the upper hull on each segment
    # Segment i uses tangent from x[i]: u(t) = fx[i] + dfx[i] * (t - x[i])
    areas <- numeric(m)
    for (i in 1:m) {
      lo <- z_all[i]
      hi <- z_all[i + 1]
      if (abs(dfx[i]) < 1e-12) {
        areas[i] <- exp(fx[i]) * (hi - lo)
      } else {
        areas[i] <- exp(fx[i]) * (exp(dfx[i] * (hi - x[i])) - exp(dfx[i] * (lo - x[i]))) / dfx[i]
      }
    }

    total_area <- sum(areas)
    if (total_area <= 0 || is.na(total_area) || is.infinite(total_area)) {
      stop("Upper hull area is non-positive or invalid. The density may not be log-concave or the domain is invalid.")
    }

    # Sample a segment proportional to area
    probs <- areas / total_area
    seg <- sample(1:m, size = 1, prob = probs)

    # Sample uniformly from the exponential distribution on the chosen segment
    lo <- z_all[seg]
    hi <- z_all[seg + 1]
    a <- dfx[seg]
    b <- fx[seg] - dfx[seg] * x[seg]

    if (abs(a) < 1e-12) {
      samples[k + 1] <- runif(1, lo, hi)
    } else {
      u <- runif(1)
      samples[k + 1] <- log(u * exp(a * hi) + (1 - u) * exp(a * lo)) / a
    }

    # Squeeze test
    t_val <- fx[seg] + dfx[seg] * (samples[k + 1] - x[seg])

    # Lower hull value at the sampled point
    if (samples[k + 1] <= x[1]) {
      l_val <- fx[1]
    } else if (samples[k + 1] >= x[m]) {
      l_val <- fx[m]
    } else {
      l_val <- NA_real_
      for (i in 1:(m - 1)) {
        if (samples[k + 1] >= x[i] && samples[k + 1] <= x[i + 1]) {
          w <- (samples[k + 1] - x[i]) / (x[i + 1] - x[i])
          l_val <- fx[i] * (1 - w) + fx[i + 1] * w
          break
        }
      }
    }

    if (is.na(l_val)) {
      # Fallback: use the nearest tangent
      l_val <- fx[seg]
    }

    # Squeeze test
    if (log(runif(1)) <= l_val - t_val) {
      k <- k + 1
      next
    }

    # Rejection test: evaluate log_f at the sampled point
    f_sampled <- log_f(samples[k + 1], ...)
    if (is.na(f_sampled) || is.nan(f_sampled) || is.infinite(f_sampled)) {
      warning(paste("log_f returned invalid value at x =", samples[k + 1], ". Rejecting sample."))
      next
    }

    if (log(runif(1)) <= f_sampled - t_val) {
      k <- k + 1
    }
    # else reject and try again (loop continues)
  }

  return(samples)
}

# ---------------------------------------------------------------------------
# Test function
# ---------------------------------------------------------------------------
test <- function() {
  cat("=== Adaptive Rejection Sampler Tests ===\n\n")

  # Test 1: Normal distribution
  cat("Test 1: Sampling from a standard normal distribution (log-concave)\n")
  set.seed(42)
  normal_log_f <- function(x) -0.5 * x^2
  normal_samples <- ars(normal_log_f, n = 10000, domain = c(-Inf, Inf))
  normal_mean <- mean(normal_samples)
  normal_sd <- sd(normal_samples)
  cat(sprintf("  Mean: %.4f (expected: 0.0000)\n", normal_mean))
  cat(sprintf("  SD:   %.4f (expected: 1.0000)\n", normal_sd))
  if (abs(normal_mean) < 0.1 && abs(normal_sd - 1) < 0.15) {
    cat("TEST_NORMAL: PASS\n")
  } else {
    cat("TEST_NORMAL: FAIL\n")
  }
  cat("\n")

  # Test 2: Exponential distribution
  cat("Test 2: Sampling from an exponential distribution (log-concave)\n")
  set.seed(123)
  exp_log_f <- function(x) -x
  exp_samples <- ars(exp_log_f, n = 10000, domain = c(0, Inf))
  exp_mean <- mean(exp_samples)
  exp_sd <- sd(exp_samples)
  cat(sprintf("  Mean: %.4f (expected: 1.0000)\n", exp_mean))
  cat(sprintf("  SD:   %.4f (expected: 1.0000)\n", exp_sd))
  if (abs(exp_mean - 1) < 0.15 && abs(exp_sd - 1) < 0.15) {
    cat("TEST_EXPONENTIAL: PASS\n")
  } else {
    cat("TEST_EXPONENTIAL: FAIL\n")
  }
  cat("\n")

  # Test 3: Input validation - negative n
  cat("Test 3: Input validation (negative n)\n")
  tryCatch({
    ars(function(x) -x, n = -5, domain = c(0, Inf))
    cat("TEST_INPUT_VALIDATION_NEG_N: FAIL (no error thrown)\n")
  }, error = function(e) {
    cat("TEST_INPUT_VALIDATION_NEG_N: PASS\n")
  })

  # Test 4: Input validation - non-function log_f
  cat("Test 4: Input validation (non-function log_f)\n")
  tryCatch({
    ars("not a function", n = 10, domain = c(0, Inf))
    cat("TEST_INPUT_VALIDATION_NON_FUNC: FAIL (no error thrown)\n")
  }, error = function(e) {
    cat("TEST_INPUT_VALIDATION_NON_FUNC: PASS\n")
  })

  # Test 5: Input validation - invalid domain
  cat("Test 5: Input validation (invalid domain)\n")
  tryCatch({
    ars(function(x) -x, n = 10, domain = c(5, 2))
    cat("TEST_INPUT_VALIDATION_DOMAIN: FAIL (no error thrown)\n")
  }, error = function(e) {
    cat("TEST_INPUT_VALIDATION_DOMAIN: PASS\n")
  })

  # Test 6: Non-log-concave density (mixture of two normals)
  cat("Test 6: Non-log-concave density (mixture of two normals)\n")
  set.seed(456)
  mixture_log_f <- function(x) {
    log(0.5 * dnorm(x, -3, 1) + 0.5 * dnorm(x, 3, 1))
  }
  tryCatch({
    mixture_samples <- ars(mixture_log_f, n = 100, domain = c(-Inf, Inf))
    # Check if samples are reasonable (should be bimodal)
    hist(mixture_samples, breaks = 30, main = "Mixture of Two Normals (Non-Log-Concave) - ARS may fail or produce poor results", xlab = "x")
    cat("TEST_NON_LOG_CONCAVE: Completed (visual inspection needed for quality)\n")
  }, error = function(e) {
    cat("TEST_NON_LOG_CONCAVE: Error caught -", conditionMessage(e), "\n")
  })

  # Test 7: Save normal samples to file
  cat("\nTest 7: Saving normal samples to /app/normal_samples.txt\n")
  set.seed(42)
  normal_samples_file <- ars(function(x) -0.5 * x^2, n = 5000, domain = c(-Inf, Inf))
  write.table(normal_samples_file, file = "/app/normal_samples.txt", row.names = FALSE, col.names = FALSE)
  cat(sprintf("  Saved %d samples to /app/normal_samples.txt\n", length(normal_samples_file)))
  cat("TEST_SAVE_SAMPLES: PASS\n")
}

# Run tests if script is executed directly
if (!interactive()) {
