      }
    }

    total_area <- sum(areas)
    if (total_area <= 0 || is.na(total_area) || is.infinite(total_area)) {
      stop("Upper hull area is non-positive or invalid. The density may not be log-concave or the domain is invalid.")
    }

    # Sample a segment proportional to area
    probs <- areas / total_area
    seg <- sample(1:m, size = 1, prob = probs)

    # Sample uniformly from the exponential distribution on the chosen segment
    lo <- z_all[seg]
    hi <- z_all[seg + 1]
    a <- dfx[seg]
    b <- fx[seg] - dfx[seg] * x[seg]

    if (abs(a) < 1e-12) {
      samples[k + 1] <- runif(1, lo, hi)
    } else {
      u <- runif(1)
      samples[k + 1] <- log(u * exp(a * hi) + (1 - u) * exp(a * lo)) / a
    }

