# ---------------------------------------------------------------------------
# Helper: compute first derivative of log-density via central finite differences
# ---------------------------------------------------------------------------
compute_derivative <- function(x, log_f, h = 1e-5) {
  f_plus  <- log_f(x + h)
  f_minus <- log_f(x - h)
  if (is.infinite(f_plus) || is.infinite(f_minus) || is.na(f_plus) || is.na(f_minus)) return(NA_real_)
  (f_plus - f_minus) / (2 * h)
}

# ---------------------------------------------------------------------------
# Helper: compute second derivative of log-density via central finite differences
# ---------------------------------------------------------------------------
compute_second_derivative <- function(x, log_f, h = 1e-5) {
  f_pp <- log_f(x + h)
  f_p  <- log_f(x)
  f_mm <- log_f(x - h)
  if (any(is.infinite(c(f_pp, f_p, f_mm)) || any(is.na(c(f_pp, f_p, f_mm)))) return(NA_real_)
  (f_pp - 2 * f_p + f_mm) / (h * h)
}

# ---------------------------------------------------------------------------
# Helper: find intersection of two tangent lines
# Tangent at x_i:  y = log_f(x_i) + dlogf(x_i) * (x - x_i)
# Tangent at x_j:  y = log_f(x_j) + dlogf(x_j) * (x - x_j)
